window.CC.p.push({n:12,view:"<section class=\"view\" id=\"p12\" hidden style=\"--c:#c2185b\"><h1><i>12</i>Ophthalmology</h1><p class=\"lead\">30 sections — pick what you want to read.</p><div class=\"grid\"><h3 class=\"sg\">Part 12A</h3><div class=\"card\" data-u=\"u293\"><button class=\"open\" data-u=\"u293\"><b>Case 1</b><span>The RED EYE — Systematic Primary Care &amp; ER Triage Approach</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=The+RED+EYE+%E2%80%94+Systematic+Primary+Care+%26+ER+Triage+Approach\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u294\"><button class=\"open\" data-u=\"u294\"><b>Case 2</b><span>Acute Conjunctivitis (VIRAL, BACTERIAL, GONOCOCCAL &amp; ALLERGIC)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Conjunctivitis+%28VIRAL%2C+BACTERIAL%2C+GONOCOCCAL+%26+ALLERGIC%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u295\"><button class=\"open\" data-u=\"u295\"><b>Case 3</b><span>Neonatal Conjunctivitis (OPHTHALMIA NEONATORUM)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neonatal+Conjunctivitis+%28OPHTHALMIA+NEONATORUM%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u296\"><button class=\"open\" data-u=\"u296\"><b>Case 4</b><span>Trachoma (CHLAMYDIA TRACHOMATIS SEROVARS A, B, C)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Trachoma+%28CHLAMYDIA+TRACHOMATIS+SEROVARS+A%2C+B%2C+C%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u297\"><button class=\"open\" data-u=\"u297\"><b>Case 5</b><span>Blepharitis, Hordeolum (STYE) &amp; Chalazion</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Blepharitis%2C+Hordeolum+%28STYE%29+%26+Chalazion\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u298\"><button class=\"open\" data-u=\"u298\"><b>Case 6</b><span>DRY EYE Disease (KERATOCONJUNCTIVITIS SICCA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=DRY+EYE+Disease+%28KERATOCONJUNCTIVITIS+SICCA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u299\"><button class=\"open\" data-u=\"u299\"><b>Case 7</b><span>Preseptal Cellulitis vs. Orbital Cellulitis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Preseptal+Cellulitis+vs.+Orbital+Cellulitis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u300\"><button class=\"open\" data-u=\"u300\"><b>Case 8</b><span>Bacterial &amp; Fungal Corneal Ulcer (MICROBIAL KERATITIS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Bacterial+%26+Fungal+Corneal+Ulcer+%28MICROBIAL+KERATITIS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u301\"><button class=\"open\" data-u=\"u301\"><b>Case 9</b><span>Herpes Simplex Keratitis &amp; Herpes Zoster Ophthalmicus</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Herpes+Simplex+Keratitis+%26+Herpes+Zoster+Ophthalmicus\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u302\"><button class=\"open\" data-u=\"u302\"><b>Case 10</b><span>Chemical Ocular Burn (ALKALI VS. ACID — SECONDS MATTER!)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chemical+Ocular+Burn+%28ALKALI+VS.+ACID+%E2%80%94+SECONDS+MATTER%21%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u303\"><button class=\"open\" data-u=\"u303\"><b>Case 11</b><span>Corneal Abrasion &amp; Corneal / Intraocular Foreign Body</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Corneal+Abrasion+%26+Corneal+%2F+Intraocular+Foreign+Body\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u304\"><button class=\"open\" data-u=\"u304\"><b>Case 12</b><span>Traumatic Hyphema &amp; Open-Globe (RUPTURED GLOBE) Injury</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Traumatic+Hyphema+%26+Open-Globe+%28RUPTURED+GLOBE%29+Injury\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u305\"><button class=\"open\" data-u=\"u305\"><b>Case 13</b><span>Anterior Uveitis (IRITIS / IRIDOCYCLITIS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Anterior+Uveitis+%28IRITIS+%2F+IRIDOCYCLITIS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u306\"><button class=\"open\" data-u=\"u306\"><b>Case 14</b><span>Episcleritis vs. Scleritis</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Episcleritis+vs.+Scleritis\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u307\"><button class=\"open\" data-u=\"u307\"><b>Case 15</b><span>Pterygium &amp; Pinguecula</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pterygium+%26+Pinguecula\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><h3 class=\"sg\">Part 12B</h3><div class=\"card\" data-u=\"u308\"><button class=\"open\" data-u=\"u308\"><b>Case 16</b><span>Cataract (AGE-RELATED, METABOLIC &amp; CONGENITAL)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cataract+%28AGE-RELATED%2C+METABOLIC+%26+CONGENITAL%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u309\"><button class=\"open\" data-u=\"u309\"><b>Case 17</b><span>Primary Open-Angle Glaucoma (POAG)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Primary+Open-Angle+Glaucoma+%28POAG%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u310\"><button class=\"open\" data-u=\"u310\"><b>Case 18</b><span>Acute Angle-Closure Glaucoma (OPHTHALMIC EMERGENCY!)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Angle-Closure+Glaucoma+%28OPHTHALMIC+EMERGENCY%21%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u311\"><button class=\"open\" data-u=\"u311\"><b>Case 19</b><span>Central Retinal Artery Occlusion (CRAO — &quot;STROKE OF THE EYE&quot;)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Central+Retinal+Artery+Occlusion+%28CRAO+%E2%80%94+%22STROKE+OF+THE+EYE%22%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u312\"><button class=\"open\" data-u=\"u312\"><b>Case 20</b><span>Central Retinal Vein Occlusion (CRVO — &quot;BLOOD &amp; THUNDER&quot; FUNDUS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Central+Retinal+Vein+Occlusion+%28CRVO+%E2%80%94+%22BLOOD+%26+THUNDER%22+FUNDUS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u313\"><button class=\"open\" data-u=\"u313\"><b>Case 21</b><span>Retinal Detachment (RD) &amp; Posterior Vitreous Detachment (PVD)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Retinal+Detachment+%28RD%29+%26+Posterior+Vitreous+Detachment+%28PVD%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u314\"><button class=\"open\" data-u=\"u314\"><b>Case 22</b><span>Diabetic Retinopathy (NPDR VS. PDR &amp; MACULAR EDEMA)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Diabetic+Retinopathy+%28NPDR+VS.+PDR+%26+MACULAR+EDEMA%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u315\"><button class=\"open\" data-u=\"u315\"><b>Case 23</b><span>Hypertensive Retinopathy</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypertensive+Retinopathy\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u316\"><button class=\"open\" data-u=\"u316\"><b>Case 24</b><span>Age-Related Macular Degeneration (DRY VS. WET AMD)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Age-Related+Macular+Degeneration+%28DRY+VS.+WET+AMD%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u317\"><button class=\"open\" data-u=\"u317\"><b>Case 25</b><span>Optic Neuritis vs. Ischemic Optic Neuropathy (AION)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Optic+Neuritis+vs.+Ischemic+Optic+Neuropathy+%28AION%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u318\"><button class=\"open\" data-u=\"u318\"><b>Case 26</b><span>Papilledema vs. Pseudopapilledema</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Papilledema+vs.+Pseudopapilledema\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u319\"><button class=\"open\" data-u=\"u319\"><b>Case 27</b><span>Cranial Nerve Palsies (CN III, IV, VI) &amp; Hornerʼs Syndrome</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cranial+Nerve+Palsies+%28CN+III%2C+IV%2C+VI%29+%26+Horner%CA%BCs+Syndrome\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u320\"><button class=\"open\" data-u=\"u320\"><b>Case 28</b><span>Pupillary Abnormalities (ESSENTIAL BEDSIDE SIGNS)</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pupillary+Abnormalities+%28ESSENTIAL+BEDSIDE+SIGNS%29\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u321\"><button class=\"open\" data-u=\"u321\"><b>Case 29</b><span>Pediatric Ophthalmology — Leukocoria (RETINOBLASTOMA!), Strabismus &amp; Amblyopia</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Ophthalmology+%E2%80%94+Leukocoria+%28RETINOBLASTOMA%21%29%2C+Strabismus+%26+Amblyopia\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div><div class=\"card\" data-u=\"u322\"><button class=\"open\" data-u=\"u322\"><b>Case 30</b><span>Retinopathy of Prematurity (ROP), Congenital Glaucoma &amp; Cnldo</span></button><a class=\"g\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Retinopathy+of+Prematurity+%28ROP%29%2C+Congenital+Glaucoma+%26+Cnldo\" title=\"Search on Google\" aria-label=\"Search on Google\">G</a></div></div></section>",units:"<article class=\"view unit\" id=\"u293\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 1</span><h1>The RED EYE — Systematic Primary Care &amp; ER Triage Approach</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=The+RED+EYE+%E2%80%94+Systematic+Primary+Care+%26+ER+Triage+Approach\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><b>Red Eye</b> is the most common ocular presentation in general practice and emergency departments, ranging from benign self-limited conjunctivitis to rapidly blinding emergencies (corneal ulcer, acute angle-closure glaucoma, endophthalmitis, or scleritis).</p><h3><b>2. Etiology (Separated — Benign vs. Sight-Threatening!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Common Benign / Primary Care Causes (Typically NO Severe Pain, NO Vision Loss):</b></span></p>\n<ul>\n<li class=\"l2\">Conjunctivitis (Viral, Mild Bacterial, Allergic).</li>\n<li class=\"l2\">Blepharitis, Hordeolum (Stye), Chalazion.</li>\n<li class=\"l2\">Subconjunctival Hemorrhage (dramatic bright-red painless patch; benign unless trauma/HTN/coagulopathy!).</li>\n<li class=\"l2\">Dry Eye Syndrome, Episcleritis, Pterygium.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Sight-Threatening Emergencies (IMMEDIATE Ophthalmology Referral!):</b></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl lab\"><b>Acute Angle-Closure Glaucoma (AACG).</b></mark></li>\n<li class=\"l2\"><b>Keratitis / Corneal Ulcer</b> (Bacterial, Fungal, <i>Acanthamoeba</i>, HSV).</li>\n<li class=\"l2\"><b>Anterior Uveitis (Iritis).</b></li>\n<li class=\"l2\"><b>Scleritis.</b></li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>Orbital Cellulitis / Endophthalmitis / Open-Globe Trauma / Chemical Burn.</b></mark></li>\n</ul><h3><b>3. Essential 5-Step Bedside Exam (Every Doctor Must Do Before Treating!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Check Visual Acuity FIRST</b> (Snellen chart with patient’s glasses/pinhole — <i>EXCEPT Chemical Burn, where immediate irrigation comes BEFORE visual acuity!</i>).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Inspect Discharge &amp; Conjunctival Injection Pattern:</b></span></p>\n<ul>\n<li class=\"l2\"><i>Diffuse peripheral redness</i> = Conjunctivitis.</li>\n<li class=\"l2\"><i>Ciliary (Circumcorneal) Flush</i> (violaceous ring around corneal limbus) = <b>Iritis, Keratitis, or Acute Glaucoma!</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Assess Pupils &amp; Penlight Reactivity:</b> Fixed <b>mid-dilated pupil</b> = <b>Acute Glaucoma</b>; <b>miotic (constricted) sluggish pupil</b> = <b>Anterior Uveitis / Corneal Ulcer</b>!</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Fluorescein Dye + Cobalt-Blue Light (Rule Out Corneal Defect!).</b></span></p>\n<p class=\"num\"><span class=\"n\">5.</span><span class=\"nt\"><b>Evert Upper Eyelid</b> (if foreign-body sensation — hides subtarsal foreign bodies!).</span></p><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><p><mark class=\"hl red\"><b>⚠ 4. RED FLAGS REQUIRING URGENT OPHTHALMOLOGY REFERRAL (Mnemonic: \"RSVP + Contact Lens\")</b></mark></p></div></div><div class=\"box red\"><div class=\"bx-ic\">⚠</div><div class=\"bx-b\"><ul>\n<li class=\"l1\"><b>R</b>educed visual acuity.</li>\n<li class=\"l1\"><b>S</b>evere deep boring eye pain (not mild grit!) + Headache/Nausea/Vomiting.</li>\n<li class=\"l1\"><b>V</b>isible corneal opacity / white spot / hypopyon (pus layer in anterior chamber) / pupil asymmetry.</li>\n<li class=\"l1\"><b>P</b>hotophobia (pain when shining light into <i>either</i> eye!).</li>\n<li class=\"l1\"><b>Contact Lens Wearer</b> with ANY painful red eye (high risk of <i>Pseudomonas / Acanthamoeba</i> corneal perforation!).</li>\n</ul></div></div><p><b>Golden Prescribing Rule:</b> <b>NEVER prescribe Topical Corticosteroid (or Steroid-Antibiotic combination!) eye drops</b> for an undiagnosed red eye without slit-lamp exam — steroids cause <b>explosive worsening of HSV/Fungal corneal ulcers</b>, <b>corneal perforation</b>, and <b>steroid-induced glaucoma/cataracts</b>!</p><nav class=\"un\"><span></span><button class=\"nv\" data-u=\"u294\">Case 2 →</button></nav></article><article class=\"view unit\" id=\"u294\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 2</span><h1>Acute Conjunctivitis (VIRAL, BACTERIAL, GONOCOCCAL &amp; ALLERGIC)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Conjunctivitis+%28VIRAL%2C+BACTERIAL%2C+GONOCOCCAL+%26+ALLERGIC%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Inflammation of the transparent conjunctiva lining the inner eyelids (palpebral) and sclera (bulbar). <b>Vision and pupillary light reflexes remain NORMAL!</b></p><h3><b>2. High-Yield Differentiation of the 4 Clinical Types</b></h3><table class=\"t wide\"><tr><td><p><b>Feature</b></p></td><td><p><b>Viral Conjunctivitis </b><i><b>(#1 Overall!)</b></i></p></td><td><p><b>Bacterial Conjunctivitis</b></p></td><td><p><b>Hyperacute Gonococcal </b><i><b>(EMERGENCY!)</b></i></p></td><td><p><b>Allergic Conjunctivitis</b></p></td></tr><tr><td><p><b>Etiology</b></p></td><td><p><b>Adenovirus</b> (#1 — epidemic keratoconjunctivitis / pharyngoconjunctival</p></td><td><p class=\"num\"><span class=\"n\">S.</span><span class=\"nt\"><i>aureus</i>, <i>S. pneumoniae</i>, <i>H. influenzae</i>, <i>M. catarrhalis</i></span></p></td><td><p><i><b>Neisseria gonorrhoeae</b></i> (STI / self-inoculation)</p></td><td><p><b>IgE-mediated Type I </b>hypersensitivity (pollens, dust, vernal catarrh!)</p></td></tr><tr><td></td><td><p>fever)</p></td><td></td><td></td><td></td></tr><tr><td><p><b>Discharge</b></p></td><td><p><b>Watery, serous</b></p></td><td><p><b>Mucopurulent</b> (eyelids glued shut in morning!)</p></td><td><p><b>COPIOUS, thick, rapidly re-accumulating yellow-green PUS!</b></p></td><td><p><b>Watery / Stringy mucoid</b></p></td></tr><tr><td><p><b>Laterality &amp; Clues</b></p></td><td><p>Starts unilateral -&gt; becomes <b>bilateral</b> in 2–3 days; concurrent <b>URTI/sore throat</b> + <b>preauricular lymphadenopathy</b> + <b>follicles</b></p></td><td><p>Usually unilateral or bilateral; <b>papillae</b>; NO preauricular node</p></td><td><p>Rapidly progresses within <b>12– 24 hrs</b> -&gt; severe lid edema + <b>CORNEAL PERFORATION RISK!</b></p></td><td><p><b>ALWAYS BILATERAL</b> + <mark class=\"hl lab\"><b>INTENSE ITCHING (Pruritus!) </b></mark>+ Chemosis + <b>\"Cobblestone\" giant papillae</b> (Vernal!)</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><b>Self-limited (1–2 wks)! </b>Cold compresses + <b>preservative-free artificial tears</b> + strict hand hygiene (<b>NO antibiotics!</b>)</p></td><td><p><b>Topical Fluoroquinolone</b> (Moxifloxacin/Ofloxacin) OR <mark class=\"hl rx\"><b>Erythromycin/Azithromycin/Polymyxin-TMP</b></mark> drops × 5–7 days <i>(Use antipseudomonal Fluoroquinolone if contact lens wearer!)</i></p></td><td><p><mark class=\"hl rx\"><b>IM Ceftriaxone 1 g SINGLE DOSE</b></mark> (+ Azithromycin/Doxycycline for <i>Chlamydia</i> co-infection!) + <b>Saline lavage</b> + Urgent Ophthalmology!</p></td><td><p>Cold compresses + <b>Dual-action Topical Antihistamine/Mast-cell Stabilizer</b> (<b>Olopatadine / Ketotifen</b>) + avoid rubbing!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u293\">← Case 1</button><button class=\"nv\" data-u=\"u295\">Case 3 →</button></nav></article><article class=\"view unit\" id=\"u295\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 3</span><h1>Neonatal Conjunctivitis (OPHTHALMIA NEONATORUM)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Neonatal+Conjunctivitis+%28OPHTHALMIA+NEONATORUM%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Purulent conjunctivitis occurring within the <b>first 28 days (4 weeks) of life</b>.</p><h3><b>2. Etiology &amp; Classic Timeline (Separated — Memorize the Days!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>First 24 Hours:</b> <b>Chemical Conjunctivitis</b> (silver nitrate — now rare; mild self-limited tearing).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Days 2 – 5 (EMERGENCY!):</b> <i><b>Neisseria gonorrhoeae</b></i> — profuse, explosive, hyperacute purulent discharge + severe eyelid swelling -&gt; <b>rapid corneal ulceration &amp; perforation leading to blindness!</b></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Days 5 – 14 (</b>#1 Bacterial Cause Overall!<b>):</b> <i><b>Chlamydia trachomatis</b></i> — mucopurulent/blood-tinged discharge, lid swelling; associated with <b>afebrile \"staccato\" neonatal pneumonia</b>!</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Days 6 – 14+:</b> <b>HSV-2</b> (Herpes Simplex Virus — vesicular lid lesions + dendritic keratitis -&gt; risk of <b>disseminated CNS neonatal herpes!</b>) or <i>S. aureus / H. influenzae</i>.</span></p>\n<p><b>3. Investigations &amp; Treatment (ALWAYS Obtain Conjunctival Gram Stain + Culture + Chlamydia/Gonorrhea NAAT!)</b></p>\n<ul>\n<li class=\"l1\"><b>Gonococcal (Days 2–5):</b> <b>Admit Newborn</b> -&gt; <mark class=\"hl rx\"><b>Single Dose IV/IM Ceftriaxone (25–50 mg/kg, max 125–250 mg)</b></mark> <i>(use Cefotaxime if hyperbilirubinemic/jaundiced!)</i> + frequent <b>saline eye irrigation</b> + treat mother &amp; partner!</li>\n<li class=\"l1\"><b>Chlamydial (Days 5–14):</b> <b>Oral Erythromycin (50 mg/kg/day × 14 days)</b> OR <mark class=\"hl rx\"><b>Oral Azithromycin (20 mg/kg/day × 3 days)</b></mark> (<mark class=\"hl lab\"><b> SYSTEMIC therapy is MANDATORY</b></mark> — topical drops fail to eradicate nasopharyngeal carriage and prevent Chlamydial pneumonia!; warn parents about slight <i>Pyloric Stenosis</i> risk with early Erythromycin!).</li>\n<li class=\"l1\"><b>HSV:</b> <mark class=\"hl rx\"><b>IV Acyclovir</b></mark> + Topical Trifluridine/Ganciclovir!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u294\">← Case 2</button><button class=\"nv\" data-u=\"u296\">Case 4 →</button></nav></article><article class=\"view unit\" id=\"u296\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 4</span><h1>Trachoma (CHLAMYDIA TRACHOMATIS SEROVARS A, B, C)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Trachoma+%28CHLAMYDIA+TRACHOMATIS+SEROVARS+A%2C+B%2C+C%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Chronic recurrent keratoconjunctivitis caused by <i><b>Chlamydia trachomatis</b></i><b> (serotypes A–C)</b> transmitted by eye-seeking flies (<i>Musca sorbens</i>), fingers, and fomites; historically the <b>#1 infectious cause of preventable blindness worldwide</b> (still encountered in elderly patients from rural Egypt with late scarring!).</p><h3><b>2. Pathophysiology (WHO \"FISTO\" Progression)</b></h3><p>Repeated childhood infections -&gt; upper tarsal <b>follicles</b> -&gt; chronic subepithelial scarring (<b>Arlt’s line</b>) -&gt; inward contracture of eyelid (<b>Entropion</b>) -&gt; eyelashes rub continuously against cornea (<b>Trichiasis</b>) -&gt; mechanical corneal abrasion, scarring, <b>Herbert’s pits</b> at superior limbus, and blindness!</p><h3><b>3. Treatment (WHO \"SAFE\" Strategy)</b></h3><ul>\n<li class=\"l1\"><b>S</b>urgery: Bilamellar tarsal rotation for <b>Trichiasis/Entropion</b> (prevents corneal blindness!).</li>\n<li class=\"l1\"><b>A</b>ntibiotics: <mark class=\"hl rx\"><b>Single-dose Oral Azithromycin (20 mg/kg, max 1 g)</b></mark> (or topical Tetracycline 1% ointment × 6 wks) for active infection/communities.</li>\n<li class=\"l1\"><b>F</b>acial Cleanliness (reduces fly attraction).</li>\n<li class=\"l1\"><b>E</b>nvironmental Improvement (clean water &amp; sanitation).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u295\">← Case 3</button><button class=\"nv\" data-u=\"u297\">Case 5 →</button></nav></article><article class=\"view unit\" id=\"u297\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 5</span><h1>Blepharitis, Hordeolum (STYE) &amp; Chalazion</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Blepharitis%2C+Hordeolum+%28STYE%29+%26+Chalazion\">🔍 Search on Google</a></header><h3><b>1. Definitions &amp; High-Yield Comparison</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Condition</b></p></th><th><p><b>Pathophysiology &amp; Gland Involved</b></p></th><th><p><b>Clinical Picture</b></p></th><th><p><b>Treatment</b></p></th></tr><tr><td><p><b>Blepharitis</b></p></td><td><p>Chronic inflammation of eyelid margins (<b>Anterior:</b> Staph/Seborrheic at eyelash base; <b>Posterior:</b> <b>Meibomian Gland Dysfunction [MGD]</b> — linked to <b>Rosacea</b>!)</p></td><td><p>Gritty burning eyes (worse on waking!), <b>red thickened lid margins</b>, greasy scales/<b>collarettes</b> around lashes, plugged meibomian orifices</p></td><td><p><b>Cornerstone = Daily Warm Compresses + Lid Margin Hygiene/Scrubs</b> (diluted baby shampoo or commercial lid wipes) + Artificial tears + <mark class=\"hl rx\"><b>Topical Azithromycin / Erythromycin</b></mark> (or low-dose <mark class=\"hl rx\"><b>Oral Doxycycline</b></mark> for severe posterior MGD/Rosacea!)</p></td></tr><tr><td><p><b>Hordeolum (Stye)</b></p></td><td><p><b>Acute painful bacterial (</b><i><b>S. aureus</b></i><b>)</b></p></td><td><p><mark class=\"hl lab\"><b>ACUTE, PAINFUL, RED, TENDER pustular</b></mark></p></td><td><p><b>Warm Compresses 10–15 min QID</b> (most</p></td></tr><tr><td></td><td><p><b>abscess</b> of <b>Gland of Zeis/Moll </b>(External) or <b>Meibomian gland </b>(Internal)</p></td><td><p><mark class=\"hl lab\"><b>nodule</b></mark> on eyelid margin pointing outward/inward</p></td><td><p>drain spontaneously!) + Topical antibiotic ointment ONLY if spreading; <i>Oral antibiotics ONLY if preseptal cellulitis develops!</i></p></td></tr><tr><td><p><b>Chalazion</b></p></td><td><p><b>Chronic, sterile lipogranulomatous inflammation</b> of a <b>blocked Meibomian gland</b> (NOT infectious!)</p></td><td><p><mark class=\"hl dx\"><b>CHRONIC, PAINLESS, FIRM, non-tender rubbery nodule</b></mark> inside the tarsal plate (<b>away from lid margin!</b>)</p></td><td><p><b>Warm Compresses + Gentle Lid Massage </b>× 4–6 wks -&gt; if persistent &gt; 1–2 mos -&gt; <b>Incision &amp; Curettage (from conjunctival side)</b> or Intralesional Triamcinolone! <i>(</i><i><b>RED FLAG:</b></i><i> Recurrent chalazion in SAME spot in elderly -&gt; </i><mark class=\"hl mech\"><i><b>BIOPSY to rule out Sebaceous Gland Carcinoma</b></i></mark><i> !)</i></p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u296\">← Case 4</button><button class=\"nv\" data-u=\"u298\">Case 6 →</button></nav></article><article class=\"view unit\" id=\"u298\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 6</span><h1>DRY EYE Disease (KERATOCONJUNCTIVITIS SICCA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=DRY+EYE+Disease+%28KERATOCONJUNCTIVITIS+SICCA%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Multifactorial disorder of the <b>tear film</b> causing tear hyperosmolarity, ocular surface inflammation, and symptoms of discomfort/visual disturbance.</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Evaporative Dry Eye (~80% — Most Common!):</b> <b>Meibomian Gland Dysfunction (MGD)</b> (blepharitis/rosacea), <b>prolonged screen time</b> (reduced blink rate!), contact lens wear, dry dusty/windy Egyptian climate, <b>Vitamin A deficiency</b> (Bitot’s spots!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Aqueous-Deficient Dry Eye:</b> Age-related lacrimal decline, <b>Sjögren’s Syndrome</b> (autoimmune dry eyes + dry mouth — screen with <b>Anti-Ro/SSA, Anti-La/SSB</b>!), <mark class=\"hl lab\"><b>RA/SLE</b></mark> , <b>Systemic Medications</b> (<b>Antihistamines</b>, <b>Antidepressants/TCAs</b>, <b>Isotretinoin</b>, <b>Beta-blockers</b>, <b>Diuretics</b>).</span></p><h3><b>3. Clinical Picture &amp; Investigations</b></h3><ul>\n<li class=\"l1\">Gritty/sandy foreign-body sensation, burning, paradoxical <b>reflex watery tearing</b> (wind/AC!), blurred vision that improves with blinking, worse late in the day!</li>\n<li class=\"l1\"><b>Diagnostic Tests:</b> <b>Tear Break-Up Time (TBUT &lt; 10 sec)</b>, <b>Schirmer’s Test (&lt; 5–10 mm wetting in 5 min)</b>, Fluorescein/Lissamine green corneal staining.</li>\n</ul><h3><b>4. Treatment</b></h3><ul>\n<li class=\"l1\"><b>Preservative-Free Artificial Tears</b> (Carboxymethylcellulose / Sodium Hyaluronate — use <b>preservative-free</b> if ≥ 4×/day to avoid BAC toxicity!) + thick lubricating gel/ointment at bedtime.</li>\n<li class=\"l1\">Treat <b>MGD/Blepharitis</b> (warm compresses + lid hygiene) + take screen breaks (<b>20-20-20 rule</b>) + Omega-3 diet.</li>\n<li class=\"l1\"><i>Moderate-Severe:</i> <mark class=\"hl rx\"><b>Topical Cyclosporine 0.05%</b></mark> or <b>Lifitegrast</b> drops + <b>Punctal Plugs</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u297\">← Case 5</button><button class=\"nv\" data-u=\"u299\">Case 7 →</button></nav></article><article class=\"view unit\" id=\"u299\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 7</span><h1>Preseptal Cellulitis vs. Orbital Cellulitis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Preseptal+Cellulitis+vs.+Orbital+Cellulitis\">🔍 Search on Google</a></header><p><i>(CRITICAL EMERGENCY DISTINCTION: </i><i><b>Preseptal</b></i><i> = Outpatient Oral Pills; </i><mark class=\"hl lab\"><i><b>Orbital</b></i></mark><i> = Admit + IV Antibiotics + Sight/Life Threat!)</i></p><h3><b>1. Anatomical Boundary &amp; Etiology</b></h3><p>Separated by the <b>Orbital Septum</b>:</p>\n<ul>\n<li class=\"l1\"><b>Preseptal Cellulitis:</b> Infection anterior to septum (eyelid skin/subcutaneous tissue only — triggered by eyelid scratch, insect bite, hordeolum, or URTI).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Orbital Cellulitis:</b></mark> Infection posterior to septum inside the bony orbit (<b>&gt; 80% spreads from Ethmoid Sinusitis!</b>). Pathogens: <i>S. aureus</i>, <i>S. pneumoniae</i>, <i>S. pyogenes</i>, Anaerobes (<i>Mucorales/Aspergillus</i> in DKA/immunocompromised!).</li>\n</ul><h3><b>2. Crucial Clinical Comparison</b></h3><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Preseptal Cellulitis</b></p></th><th><p><mark class=\"hl lab\"><b>Orbital Cellulitis </b></mark><i><b>(TRUE EMERGENCY!)</b></i></p></th></tr><tr><td><p><b>Eyelid Swelling &amp; Redness</b></p></td><td><p>Yes (warm, tender, swollen eyelid)</p></td><td><p>Yes</p></td></tr><tr><td><p><b>Visual Acuity</b></p></td><td><p><b>NORMAL</b></p></td><td><p><b>DECREASED!</b></p></td></tr><tr><td><p><b>Extraocular Movements (EOM)</b></p></td><td><p><b>Full &amp; Painless</b></p></td><td><p><b>RESTRICTED (Ophthalmoplegia) &amp; PAINFUL eye movements!</b></p></td></tr><tr><td><p><b>Proptosis (Bulging Eye)</b></p></td><td><p><b>ABSENT</b></p></td><td><p><b>PRESENT!</b></p></td></tr><tr><td><p><b>Pupillary Reflex / Systemic</b></p></td><td><p>Normal RAPD (-); mild/no fever</p></td><td><p><b>RAPD (+)</b> (optic nerve compression!), chemosis, high fever, toxic!</p></td></tr><tr><td><p><b>Imaging &amp; Treatment</b></p></td><td><p>Clinical diagnosis (CT only if unsure); <mark class=\"hl rx\"><b>Oral Amoxicillin-Clavulanate</b></mark> (or Cephalexin/TMP-SMX if MRSA) + close 24-hr follow-up!</p></td><td><p><b>STAT Contrast CT Orbits &amp; Sinuses</b> + <b>Admit -&gt; IV Broad-Spectrum Antibiotics</b> (<mark class=\"hl rx\"><b> Vancomycin + Ceftriaxone/Ampicillin-Sulbactam + Metronidazole</b></mark> ) + <b>Urgent ENT/Ophthalmology Consult</b> for abscess drainage!</p></td></tr></table><ul>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Feared Complications of Orbital Cellulitis:</b></mark> <b>Cavernous Sinus Thrombosis</b> (bilateral orbital signs + CN III/IV/V/VI palsies + high fever!), Subperiosteal abscess, Meningitis, Permanent blindness!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u298\">← Case 6</button><button class=\"nv\" data-u=\"u300\">Case 8 →</button></nav></article><article class=\"view unit\" id=\"u300\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 8</span><h1>Bacterial &amp; Fungal Corneal Ulcer (MICROBIAL KERATITIS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Bacterial+%26+Fungal+Corneal+Ulcer+%28MICROBIAL+KERATITIS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p><b>Sight-threatening infection of the corneal stroma</b> accompanied by an <b>overlying epithelial defect</b>, posing high risk of <b>corneal perforation and permanent scarring/blindness</b>!</p><h3><b>2. Etiology &amp; Risk Factors (Separated — ALWAYS ASK ABOUT CONTACT LENSES &amp; FARMING TRAUMA!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Contact Lens Wearers (#1 Risk Factor in Cities):</b> <i><b>Pseudomonas aeruginosa</b></i> (rapidly melts cornea within 24–48 hrs!) and <i><b>Acanthamoeba</b></i> (swimming/tap water exposure -&gt; <b>excruciating pain OUT OF PROPORTION to exam</b> + <b>ring-shaped infiltrate</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Agricultural / Vegetative Trauma (Very Common in Rural Egypt!):</b> <b>Fungal Keratitis</b> (<i><b>Fusarium, Aspergillus, Candida</b></i> — tree branch/wheat stalk scratch!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Dry Eye / Lid Malposition / Chronic Topical Steroid Abuse:</b> <i>Staphylococcus aureus</i>, <i>Streptococcus pneumoniae</i>.</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Severe eye pain, photophobia, tearing, red eye (ciliary flush), and decreased vision!</b></li>\n<li class=\"l1\"><b>Exam:</b> <b>White/gray corneal stromal infiltrate (white spot on the clear cornea!)</b> staining <b>bright green with Fluorescein</b>, often accompanied by a <b>Hypopyon</b> (layer of white pus settled at the bottom of the anterior chamber!).</li>\n<li class=\"l1\"><i>Fungal Clues:</i> Grayish-white infiltrate with <b>\"feathery\" irregular margins</b> and <b>satellite lesions</b>!</li>\n</ul><h3><b>4. Management (TRUE OPHTHALMIC EMERGENCY!)</b></h3><ul>\n<li class=\"l1\"><b>IMMEDIATE Same-Day Ophthalmology Referral</b> for <b>Corneal Scraping (Gram stain, KOH, Bacterial/Fungal cultures)</b> BEFORE starting empirical drops!</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><i>Bacterial:</i> Intensive <mark class=\"hl rx\"><b>Fortified Topical Antibiotics (Vancomycin + Tobramycin/Ceftazidime)</b></mark> OR <b>4th-Gen Fluoroquinolone (Moxifloxacin/Gatifloxacin)</b> instilled <b>every 15–60 minutes around the clock</b>! (Add Cycloplegic drop like Cyclopentolate for pain/synechiae!).</li>\n<li class=\"l2\"><i>Fungal:</i> <b>Topical Natamycin 5%</b> (for <i>Fusarium/Aspergillus</i>) or <b>Voriconazole / Amphotericin B</b>!</li>\n<li class=\"l1\"><b>CONTRAINDICATIONS:</b> <b>NEVER patch a suspected infected corneal ulcer</b> (incubates <i>Pseudomonas</i>!), and <b>NEVER give Topical Steroids initially</b>!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u299\">← Case 7</button><button class=\"nv\" data-u=\"u301\">Case 9 →</button></nav></article><article class=\"view unit\" id=\"u301\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 9</span><h1>Herpes Simplex Keratitis &amp; Herpes Zoster Ophthalmicus</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Herpes+Simplex+Keratitis+%26+Herpes+Zoster+Ophthalmicus\">🔍 Search on Google</a></header><h3><b>A. Herpes Simplex Keratitis (HSV-1)</b></h3><ul>\n<li class=\"l1\"><b>Clinical Picture:</b> Unilateral red eye, tearing, photophobia, foreign-body sensation, blurred vision, decreased <b>corneal sensation</b>!</li>\n<li class=\"l1\"><b>Pathognomonic Fluorescein Sign:</b> Classic branching <b>\"DENDRITIC ULCER\" with terminal bulbs</b>!</li>\n<li class=\"l1\"><b>CRITICAL CONTRAINDICATION:</b> <b>TOPICAL CORTICOSTEROIDS ARE STRICTLY CONTRAINDICATED</b> in epithelial HSV keratitis — steroids convert a small dendritic ulcer into a massive <b>\"Geographic Ulcer\"</b> risking corneal perforation!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Topical Ganciclovir 0.15% gel</b> (or Trifluridine drops) <mark class=\"hl rx\"><b>AND/OR Oral Acyclovir (400 mg 5×/day) / Valacyclovir (500 mg TID)</b></mark> × 7–10 days!</li>\n</ul><h3><b>B. Herpes Zoster Ophthalmicus (VZV — CN V1)</b></h3><ul>\n<li class=\"l1\"><b>Clinical Clue:</b> Painful unilateral vesicular rash on forehead, upper eyelid, and <b>tip/side of nose (Hutchinson’s Sign = Nasociliary nerve involvement -&gt; &gt; 75% risk of ocular involvement!)</b>.</li>\n<li class=\"l1\"><b>Treatment:</b> <mark class=\"hl rx\"><b>Oral Valacyclovir 1,000 mg TID</b></mark> (or Acyclovir 800 mg 5×/day) started <b>within 72 hours</b> + urgent Ophthalmology slit-lamp check for keratitis/uveitis!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u300\">← Case 8</button><button class=\"nv\" data-u=\"u302\">Case 10 →</button></nav></article><article class=\"view unit\" id=\"u302\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 10</span><h1>Chemical Ocular Burn (ALKALI VS. ACID — SECONDS MATTER!)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Chemical+Ocular+Burn+%28ALKALI+VS.+ACID+%E2%80%94+SECONDS+MATTER%21%29\">🔍 Search on Google</a></header><h3><b>1. Pathophysiology (ALKALI IS FAR WORSE THAN ACID!)</b></h3><ul>\n<li class=\"l1\"><b>ALKALI BURNS</b> (<b>Ammonia, Lye/Drain cleaners, Lime/Cement/Plaster [</b><i><b>Geer/Asmant</b></i><b> in Egypt!]</b>): Cause <mark class=\"hl lab\"><b>LIQUEFACTIVE NECROSIS</b></mark> (saponifies cell membranes -&gt; penetrates rapidly deep into cornea, anterior chamber, and ciliary body within minutes -&gt; catastrophic blindness!).</li>\n<li class=\"l1\"><b>ACID BURNS</b> (Battery acid, Sulfuric/Hydrochloric acid): Cause <mark class=\"hl lab\"><b>COAGULATIVE NECROSIS</b></mark> (precipitates surface proteins, creating a barrier that limits deeper penetration — <i>except Hydrofluoric acid!</i>).</li>\n</ul>\n<p><b>2. IMMEDIATE TREATMENT (DO NOT TAKE HISTORY, DO NOT CHECK VISUAL ACUITY, DO NOT WAIT FOR OPHTHALMOLOGIST!)</b></p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>IMMEDIATE COPIOUS CONTINUOUS IRRIGATION:</b> Instill 1 drop of topical anesthetic (Proparacaine) to relieve blepharospasm -&gt; irrigate continuously with <b>2–3+ Liters of Normal Saline or Ringer’s Lactate</b> (or clean tap water immediately at scene!) for <b>at least 30 MINUTES</b>!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Sweep Fornices &amp; Evert Eyelids</b> with a moistened cotton swab to remove hidden <b>lime/cement particles</b>!</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Check Conjunctival Fornix pH</b> with litmus paper 5–10 minutes after stopping irrigation -&gt; <b>KEEP IRRIGATING until pH normalizes to 7.0–7.4</b>!</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Urgent Ophthalmology Referral</b> (assess <b>Limbal Ischemia [blanched white limbus = worst prognosis!]</b> -&gt; treat with topical antibiotics, <b>topical steroids [first 7–10 days ONLY!]</b>, <mark class=\"hl rx\"><b>Oral Doxycycline + Vitamin C</b></mark> [prevent corneal melting!], cycloplegics!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u301\">← Case 9</button><button class=\"nv\" data-u=\"u303\">Case 11 →</button></nav></article><article class=\"view unit\" id=\"u303\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 11</span><h1>Corneal Abrasion &amp; Corneal / Intraocular Foreign Body</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Corneal+Abrasion+%26+Corneal+%2F+Intraocular+Foreign+Body\">🔍 Search on Google</a></header><h3><b>1. Corneal Abrasion</b></h3><ul>\n<li class=\"l1\"><b>Etiology:</b> Fingernail scratch, paper edge, mascara brush, contact lens, wind-blown dust.</li>\n<li class=\"l1\"><b>Clinical:</b> Acute sharp pain, tearing, blepharospasm, photophobia; <b>Fluorescein Stain</b> under cobalt-blue light shows bright green epithelial defect!</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><b>Topical Antibiotic Ointment/Drops</b> (Erythromycin or Polymyxin-TMP; <mark class=\"hl rx\"><b>MUST use Topical Fluoroquinolone [Moxifloxacin/Ciprofloxacin] in Contact Lens wearers</b></mark> and tell them <b>DO NOT wear lenses until healed!</b>).</li>\n<li class=\"l2\"><b>Oral analgesia</b> (NSAIDs/Acetaminophen).</li>\n<li class=\"l2\"><b>DO NOT:</b> <b>Do NOT patch</b> contact-lens or dirty/organic abrasions; <b>NEVER prescribe Topical Anesthetic drops (Proparacaine/Tetracaine) to take home</b> (causes toxic corneal melting &amp; perforation!).</li>\n</ul><h3><b>2. Corneal Foreign Body vs. Intraocular Foreign Body (IOFB)</b></h3><ul>\n<li class=\"l1\"><b>Superficial Corneal FB:</b> Always <b>evert upper eyelid</b> (look for <b>vertical linear corneal scratches</b> indicating a hidden subtarsal FB!). Remove under slit-lamp using topical anesthetic + moistened cotton tip or sterile 25G needle bevel-up (remove iron <b>\"rust ring\"</b>!).</li>\n<li class=\"l1\"><b>HIGH-VELOCITY METAL-ON-METAL / HAMMERING HISTORY:</b> Suspect <b>Penetrating Intraocular Foreign Body (IOFB)</b> -&gt; <b>DO NOT pull out protruding objects, DO NOT press on globe</b> -&gt; <mark class=\"hl mech\"><b>CT Orbits (NO MRI — metallic FB moves!)</b></mark> + IV antibiotics + emergent vitreoretinal surgery!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u302\">← Case 10</button><button class=\"nv\" data-u=\"u304\">Case 12 →</button></nav></article><article class=\"view unit\" id=\"u304\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 12</span><h1>Traumatic Hyphema &amp; Open-Globe (RUPTURED GLOBE) Injury</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Traumatic+Hyphema+%26+Open-Globe+%28RUPTURED+GLOBE%29+Injury\">🔍 Search on Google</a></header><h3><b>A. Traumatic Hyphema</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Accumulation of <b>blood in the Anterior Chamber</b> (visible red fluid meniscus in front of iris) following blunt eye trauma (fist, ball, airbag).</li>\n<li class=\"l1\"><b>Complications:</b> <b>Secondary Glaucoma</b> (RBCs clog trabecular meshwork), <b>Corneal Blood Staining</b> (permanent rust-brown opacity!), and <b>Re-bleeding</b> (highest on <b>Days 2–5</b>!).</li>\n<li class=\"l1\"><b>CRITICAL RULE:</b> <b>Screen African/Mediterranean patients for SICKLE CELL TRAIT/DISEASE</b> (even sickle <i>trait</i> causes catastrophic sickling in anterior chamber -&gt; extreme IOP spike; <mark class=\"hl rx\"><b>avoid Acetazolamide/Mannitol in Sickle Cell</b></mark> — causes metabolic acidosis worsening sickling -&gt; use Methazolamide/Timolol/Brimonidine!).</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Rigid Eye Shield</b>, <b>Bed rest with Head of Bed elevated 30–45°</b> (allows blood to settle downward!), <mark class=\"hl rx\"><b>Cycloplegic (Atropine)</b></mark> + <b>Topical Steroids</b>, <mark class=\"hl rx\"><b>NO Aspirin/NSAIDs</b></mark> , daily IOP check!</li>\n</ul><h3><b>B. Open-Globe Injury (Ruptured / Lacerated Globe — SURGICAL EMERGENCY!)</b></h3><ul>\n<li class=\"l1\"><b>Red Flags:</b> <b>Teardrop / Peaked Pupil</b> (iris prolapsing toward laceration!), <b>Flat/Shallow Anterior Chamber</b>, <b>360° Bullous Subconjunctival Hemorrhage</b>, <b>Uveal (brown/black) tissue prolapse</b>, markedly low IOP, severe vision loss!</li>\n<li class=\"l1\"><b>IMMEDIATE ER ACTION (DO NOT TOUCH THE EYE!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>STOP EXAM IMMEDIATELY</b> — <mark class=\"hl mech\"><b>NO Tonometry (IOP check), NO Fluorescein, NO Eye Drops/Ointments, NO Lid Speculum/Pressure!</b></mark></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\">Tape a <b>RIGID FOX EYE SHIELD</b> over the orbit (rests on bony rim, NOT on globe!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>NPO</b> (for OR), <b>IV Broad-Spectrum Antibiotics</b> (Vancomycin + Ceftazidime to prevent Endophthalmitis!), <b>IV Antiemetics (Ondansetron)</b> &amp; <b>Pain Control </b>(vomiting/straining raises IOP and extrudes eye contents!), <b>Tetanus shot</b>, <b>CT Orbits</b> -&gt; <b>Emergent Surgical Globe Repair</b>!</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u303\">← Case 11</button><button class=\"nv\" data-u=\"u305\">Case 13 →</button></nav></article><article class=\"view unit\" id=\"u305\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 13</span><h1>Anterior Uveitis (IRITIS / IRIDOCYCLITIS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Anterior+Uveitis+%28IRITIS+%2F+IRIDOCYCLITIS%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Inflammation of the <b>iris and ciliary body</b> (uveal tract).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Idiopathic (~50%).</b></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl mech\"><b>HLA-B27 Associated (~20–30% — Acute Unilateral Recurrent!):</b></mark> <mark class=\"hl lab\"><b>Ankylosing Spondylitis</b></mark> , <mark class=\"hl lab\"><b>Reactive Arthritis</b></mark> , <mark class=\"hl lab\"><b>IBD</b></mark> , Psoriatic Arthritis.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Systemic Autoimmune / Inflammatory:</b> <b>Sarcoidosis</b>, <b>Behçet’s Disease</b> (classic <b>hypopyon uveitis</b> + oral/genital ulcers — very relevant in Egypt!), <b>Juvenile Idiopathic Arthritis (JIA — painless silent chronic uveitis in young girls!)</b>, <mark class=\"hl lab\"><b>SLE</b></mark> .</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Infectious:</b> <b>TB</b>, <b>Syphilis</b>, <b>HSV / VZV</b>, Toxoplasmosis (posterior chorioretinitis).</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Unilateral deep aching/throbbing eye pain</b>, marked <b>PHOTOPHOBIA</b> (consensual photophobia: shining light in the <i>healthy</i> eye causes pain in the <i>affected</i> eye!), blurred vision, tearing.</li>\n<li class=\"l1\"><b>Exam:</b> <b>Ciliary (circumcorneal) flush</b>, <b>MIOTIC (constricted), sluggish, or irregular pupil</b> (posterior synechiae!), <b>NO purulent discharge</b>, <b>Slit-lamp shows \"Cells and Flare\" in Anterior Chamber</b> + <b>Keratic Precipitates (KPs)</b> on corneal endothelium!</li>\n</ul><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>First mild uncomplicated episode:</b> Often no labs needed. <b>Bilateral, recurrent, granulomatous (\"mutton-fat\" KPs), or severe:</b> Check <mark class=\"hl mech\"><b>HLA-B27, CXR/IGRA (TB/Sarcoid), Syphilis (RPR/FTA-ABS), ACE, Lyme/Behçet’s workup</b></mark> !</li>\n<li class=\"l1\"><b>Treatment (By Ophthalmologist ONLY!):</b></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl rx\"><b>Intensive Topical Corticosteroids</b></mark> (<mark class=\"hl rx\"><b> Prednisolone Acetate 1%</b></mark> ) every 1–2 hrs initially, then <b>SLOW taper</b>!</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Topical Cycloplegic / Mydriatic</b> (<mark class=\"hl rx\"><b> Cyclopentolate 1% or Homatropine/Atropine</b></mark> ) -&gt; paralyzes ciliary spasm (relieves pain!) and <b>dilates pupil to prevent Posterior Synechiae</b> (iris sticking to lens!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u304\">← Case 12</button><button class=\"nv\" data-u=\"u306\">Case 14 →</button></nav></article><article class=\"view unit\" id=\"u306\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 14</span><h1>Episcleritis vs. Scleritis</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Episcleritis+vs.+Scleritis\">🔍 Search on Google</a></header><h4><b>High-Yield Clinical Distinction (Mild vs. Severe Systemic Vasculitis Emergency!)</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Episcleritis </b><i><b>(Benign)</b></i></p></th><th><p><b>Scleritis </b><i><b>(Sight-Threatening!)</b></i></p></th></tr><tr><td><p><b>Systemic Association</b></p></td><td><p>Usually <b>Idiopathic</b> (~70%)</p></td><td><p><b>~50% Linked to Systemic Autoimmune Vasculitis:</b> <mark class=\"hl lab\"><b>Rheumatoid Arthritis (#1!)</b></mark> , <b>GPA (Wegener’s)</b>, <mark class=\"hl lab\"><b>SLE</b></mark> , <mark class=\"hl lab\"><b>PAN</b></mark> , <mark class=\"hl lab\"><b>IBD</b></mark> , <mark class=\"hl lab\"><b>Gout</b></mark> !</p></td></tr><tr><td><p><b>Pain</b></p></td><td><p>Mild discomfort / irritation (NO deep pain!)</p></td><td><p><b>EXCRUCIATING, deep \"boring\" pain</b> that <b>wakes patient from sleep at night</b> and worsens with eye movement!</p></td></tr><tr><td><p><b>Appearance &amp; Phenylephrine 2.5% Test</b></p></td><td><p><b>Sectoral bright-red superficial injection</b> that <mark class=\"hl mech\"><b>BLANCHES (turns white)</b></mark> within 10–15 min after <b>1 drop of Phenylephrine 2.5%</b>!</p></td><td><p><b>Violaceous / Bluish-red deep scleral injection</b> (painful globe tenderness) that <mark class=\"hl mech\"><b>DOES NOT BLANCH </b></mark>with Phenylephrine!</p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p>Artificial tears / Oral NSAIDs (self-limited 1–2 wks!)</p></td><td><p><b>Urgent Ophthalmology + Systemic Workup!</b> <mark class=\"hl rx\"><b>Oral NSAIDs</b></mark> -&gt; <mark class=\"hl rx\"><b>High-Dose Systemic Corticosteroids + Immunosuppressants (Methotrexate/Cyclophosphamide/Rituximab)</b></mark> ! <i>(NEVER neglect — risk of Scleromalacia Perforans!)</i></p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u305\">← Case 13</button><button class=\"nv\" data-u=\"u307\">Case 15 →</button></nav></article><article class=\"view unit\" id=\"u307\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 15</span><h1>Pterygium &amp; Pinguecula</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pterygium+%26+Pinguecula\">🔍 Search on Google</a></header><h3><b>1. Definitions &amp; Comparison (</b><b>Extremely Common in Sunny/Dusty Egyptian Climate!</b><b>)</b></h3><ul>\n<li class=\"l1\"><b>Pinguecula:</b> Benign, yellowish-white elevated degeneration of conjunctival elastotic collagen located at the <b>nasal (or temporal) bulbar conjunctiva</b> — <b>DOES NOT cross onto the Cornea</b>!</li>\n<li class=\"l1\"><b>Pterygium:</b> Triangular, <b>wing-shaped fibrovascular growth</b> of conjunctiva extending <b>ONTO THE CORNEA</b> (usually <b>nasal side</b>), driven by <b>chronic UV sunlight, wind, and dust exposure</b>!</li>\n</ul><h3><b>2. Clinical Picture &amp; Treatment</b></h3><ul>\n<li class=\"l1\">Usually asymptomatic cosmetic concern or mild dry-eye irritation; Pterygium can induce <b>astigmatism</b> or obscure the visual axis as it grows across the pupil!</li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><b>Prevention &amp; Mild Symptoms:</b> <b>UV-Blocking Sunglasses</b> + Lubricating artificial tears (brief mild topical steroid ONLY if acutely inflamed \"pingueculitis\").</li>\n<li class=\"l2\"><b>Surgical Excision (With Conjunctival Autograft +/- Mitomycin C to prevent recurrence!):</b> Indicated ONLY if Pterygium threatens the <b>visual axis</b>, induces significant <b>astigmatism</b>, restricts eye movement, or causes severe refractory irritation!</li>\n</ul>\n<p class=\"muted\"><i>End of Part 12A — Ophthalmology (Cases 1–15 Complete!).</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u306\">← Case 14</button><button class=\"nv\" data-u=\"u308\">Case 16 →</button></nav></article><article class=\"view unit\" id=\"u308\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 16</span><h1>Cataract (AGE-RELATED, METABOLIC &amp; CONGENITAL)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cataract+%28AGE-RELATED%2C+METABOLIC+%26+CONGENITAL%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Opacification (clouding) of the normally crystal-clear <b>crystalline lens</b> inside the eye, leading to painless progressive visual impairment. <b>#1 Cause of Reversible Blindness Worldwide!</b></p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Age-Related (Senile — #1 Overall, &gt; 90%):</b> Oxidative protein aggregation &amp; UV-B light accumulation (&gt; 60 years).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Metabolic &amp; Systemic Diseases:</b> <b>Diabetes Mellitus</b> (sorbitol accumulation via aldose reductase causes osmotic swelling &amp; early \"snowflake\" cataracts!), <b>Hypocalcemia</b>, <b>Galactosemia</b> (\"oil-droplet\" cataract in newborns — reversible with galactose-free diet!), <b>Wilson’s disease</b> (\"sunflower\" cataract), <b>Myotonic dystrophy</b> (\"Christmas-tree\" cataract).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Drug-Induced / Iatrogenic:</b> <mark class=\"hl rx\"><b>Long-term Corticosteroids</b></mark> (systemic/inhaled/topical -&gt; classic <b>Posterior Subcapsular Cataract</b>!), Amiodarone, Chlorpromazine.</span></p>\n<p class=\"num\"><span class=\"n\">4.</span><span class=\"nt\"><b>Traumatic / Inflammatory / Congenital:</b> Blunt/penetrating trauma (\"rosette\" cataract), Chronic anterior uveitis, <b>Congenital Rubella / TORCH</b> infections (presents as <b>Leukocoria</b> at birth!).</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Painless, gradual, progressive blurring of vision</b> over months–years.</li>\n<li class=\"l1\"><b>Glare and halos around headlights during night driving</b> (classic for Posterior Subcapsular Cataract!), faded colors (yellow-brown tint), <b>\"Second Sight\"</b> (elderly nuclear sclerosis patient suddenly able to read <i>without</i> reading glasses due to induced myopia!).</li>\n<li class=\"l1\"><b>Exam:</b> <b>Decreased Red Reflex</b>, <b>white/gray opaque pupil</b> (if mature), <b>NO pain, NO redness, NO RAPD</b> (Relative Afferent Pupillary Defect — pure cataract NEVER causes an RAPD!).</li>\n</ul><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Slit-Lamp Biomicroscopy + Dilated Fundus Exam</b> (rule out retinal pathology before promising perfect vision post-op!) + <b>Biometry</b> (corneal keratometry + axial length to calculate <b>IOL</b> [Intraocular Lens] power).</li>\n<li class=\"l1\"><b>Definitive Treatment (NO Eye Drops Dissolve Cataracts!):</b> <b>Phacoemulsification</b> (ultrasound emulsification through a micro-incision) + <b>Posterior Chamber Intraocular Lens (IOL) Implantation</b> — performed whenever visual impairment interferes with daily activities! <i>(Pre-op medication check: Ask men about </i><i><b>Tamsulosin </b></i><i>[α1A-blocker for BPH] -&gt; causes </i><i><b>Intraoperative Floppy Iris Syndrome!</b></i><i>).</i></li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u307\">← Case 15</button><button class=\"nv\" data-u=\"u309\">Case 17 →</button></nav></article><article class=\"view unit\" id=\"u309\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 17</span><h1>Primary Open-Angle Glaucoma (POAG)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Primary+Open-Angle+Glaucoma+%28POAG%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Chronic, progressive <b>optic neuropathy</b> characterized by <b>retinal ganglion cell death, optic disc cupping, and irreversible peripheral visual field loss</b>, usually (though not always!) associated with elevated <mark class=\"hl mech\"><b>IOP</b></mark> (Intraocular Pressure <b>&gt; 21 mmHg</b>) in the presence of an <b>open, normal-appearing anterior chamber angle</b>. <b>\"The Silent Thief of Sight!\"</b></p><h3><b>2. Etiology &amp; Risk Factors (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Impaired Aqueous Outflow:</b> Decreased drainage through the <b>trabecular meshwork</b> (exact cause idiopathic).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Major Risk Factors:</b> Advancing age (&gt; 60 yrs), <b>Family history</b> (1st-degree relative!), <mark class=\"hl mech\"><b>Elevated IOP</b></mark> , <b>Thin central corneal thickness</b>, <b>Myopia</b>, <b>Diabetes Mellitus</b>, chronic <b>Topical/Systemic Steroids</b> (\"steroid responders\"!).</span></p><h3><b>3. Clinical Picture (COMPLETELY ASYMPTOMATIC EARLY ON!)</b></h3><ul>\n<li class=\"l1\"><b>Painless, insidious bilateral loss of PERIPHERAL vision first</b> (\"tunnel vision\" late — <b>central 20/20 visual acuity is spared until end-stage!</b>).</li>\n<li class=\"l1\"><b>Fundoscopy:</b> <b>Enlarged Optic Cup-to-Disc Ratio (CDR &gt; 0.6 or asymmetry &gt; 0.2 between eyes)</b>, notching of neuroretinal rim, nasal displacement of retinal vessels!</li>\n</ul><h3><b>4. Investigations &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Diagnostic Triad:</b> <b>(1) Tonometry</b> (IOP &gt; 21 mmHg — note: ~30% have <i>Normal-Tension Glaucoma</i>!), <b>(2) Gonioscopy</b> (confirms <b>OPEN angle</b>), <b>(3) Automated Perimetry (Visual Field Testing)</b> (arcuate scotomas/nasal step) + <b>OCT</b> (Optical Coherence Tomography — retinal nerve fiber layer thinning!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Treatment (Goal: Lower IOP by ≥ 20–30% to Halt Optic Nerve Loss!):</b></mark></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>First-Line Eye Drops:</b> <b>Prostaglandin Analogues</b> (<b>Latanoprost, Bimatoprost, Travoprost</b> — dosed once nightly; <i>side effects: lengthens eyelashes, darkens iris pigmentation &amp; periorbital skin!</i>) <b>OR</b> <b>Topical Beta-Blockers</b> (<b>Timolol</b> — <i>AVOID in </i><mark class=\"hl lab\"><i><b>Asthma, COPD, Bradycardia, 2nd/3rd-degree AV block</b></i></mark><i> !</i>).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Second-Line Drops:</b> <b>Alpha-2 Agonists</b> (<b>Brimonidine</b> — <i>avoid in infants/children &lt; 2 yrs due to CNS depression!</i>) and <b>Topical Carbonic Anhydrase Inhibitors </b>(<b>Dorzolamide, Brinzolamide</b>).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Laser / Surgery (If drops fail or non-compliant):</b> <b>SLT</b> (Selective Laser Trabeculoplasty — increasingly offered as first-line!) or <b>Trabeculectomy</b> / Minimally Invasive Glaucoma Surgery (<b>MIGS</b>).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u308\">← Case 16</button><button class=\"nv\" data-u=\"u310\">Case 18 →</button></nav></article><article class=\"view unit\" id=\"u310\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 18</span><h1>Acute Angle-Closure Glaucoma (OPHTHALMIC EMERGENCY!)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Acute+Angle-Closure+Glaucoma+%28OPHTHALMIC+EMERGENCY%21%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Sudden mechanical blockage of the <b>trabecular meshwork</b> by the <b>peripheral iris</b> (\"pupillary block\"), causing an explosive spike in <mark class=\"hl mech\"><b>IOP (often 50–80 mmHg)</b></mark> and rapid irreversible optic nerve ischemia!</p><h3><b>2. Etiology &amp; Triggers (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Anatomical Predisposition:</b> <b>Hyperopic (farsighted) small eyes</b>, shallow anterior chamber, <b>elderly</b> (enlarging lens pushes iris forward), female sex.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Acute Pupillary Dilation Triggers (Dim Light or Drugs!):</b> Sitting in a <b>dark movie theater/room</b>, <b>Anticholinergics</b> (Atropine, Ipratropium nebulizers, Antihistamines, TCAs), <b>Sympathomimetics</b> (Phenylephrine, Pseudoephedrine decongestants), <b>Topiramate</b> (ciliary body edema!), stress.</span></p><h3><b>3. Clinical Picture (CLASSIC TRIAD — OFTEN MISDIAGNOSED AS MIGRAINE OR ACUTE ABDOMEN!)</b></h3><ul>\n<li class=\"l1\"><b>Sudden severe unilateral eye pain &amp; frontal headache</b>, <b>blurred vision with RAINBOW HALOS around lights</b> (corneal epithelial edema!), <b>NAUSEA &amp; VOMITING</b>!</li>\n<li class=\"l1\"><b>Exam:</b> Red eye (<b>ciliary flush</b>), <b>steamy/hazy cornea</b>, <b>FIXED MID-DILATED NON-REACTIVE PUPIL</b>, shallow anterior chamber, <mark class=\"hl lab\"><b>STONY-HARD EYEBALL</b></mark> on gentle palpation!</li>\n</ul><h3><b>4. Emergency Treatment (DROP IOP IMMEDIATELY -&gt; DEFINITIVE LASER!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Immediate Systemic + Topical IOP-Lowering Medications (Give ALL Together!):</b></mark></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl rx\"><b>IV/Oral Acetazolamide 500 mg</b></mark> stat (Carbonic Anhydrase Inhibitor — reduces aqueous production; <i>avoid if sulfa-anaphylaxis!</i>).</li>\n<li class=\"l2\"><b>Topical Beta-Blocker (Timolol 0.5%)</b> + <b>Topical Alpha-Agonist (Brimonidine/Apraclonidine)</b> + <b>Topical Steroid</b> (reduces inflammation).</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>Topical Pilocarpine 1–2%</b></mark> (cholinergic miotic — pulls peripheral iris out of angle! <i>Note: Works only once IOP begins falling below ~40–50 mmHg because high IOP paralyzes iris sphincter!</i>).</li>\n<li class=\"l2\"><mark class=\"hl rx\"><b>IV Mannitol (1–2 g/kg over 30–60 min)</b></mark> if IOP remains dangerously high or vomiting prevents oral meds (check HF/renal status!).</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Definitive Cure (Once Cornea Clears):</b> <b>Laser Peripheral Iridotomy (LPI)</b> in <b>BOTH EYES</b> (prophylactic LPI in the fellow eye prevents future attack!) — followed by early cataract extraction if lens-induced.</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u309\">← Case 17</button><button class=\"nv\" data-u=\"u311\">Case 19 →</button></nav></article><article class=\"view unit\" id=\"u311\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 19</span><h1>Central Retinal Artery Occlusion (CRAO — &quot;STROKE OF THE EYE&quot;)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Central+Retinal+Artery+Occlusion+%28CRAO+%E2%80%94+%22STROKE+OF+THE+EYE%22%29\">🔍 Search on Google</a></header><h3><b>1. Definition</b></h3><p>Sudden catastrophic occlusion of the <b>Central Retinal Artery</b> causing acute painless retinal infarction (<b>Ophthalmic &amp; Neurological Emergency — Irreversible Retinal Death Occurs Within 90–240 Minutes!</b>).</p><h3><b>2. Etiology (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Thromboembolism (~75–80% — #1 Overall!):</b> <mark class=\"hl dx\"><b>Carotid Artery Atherosclerosis</b></mark> (Hollenhorst cholesterol plaque!) or <b>Cardioembolism</b> (<mark class=\"hl lab\"><b> AFib</b></mark> , Valvular disease, Carotid dissection).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Vasculitis (CRITICAL IN &gt; 50 YEARS OLD!):</b> <mark class=\"hl lab\"><b>Giant Cell (Temporal) Arteritis (GCA)</b></mark> — <i>ALWAYS screen for jaw claudication, scalp tenderness, headache, and high ESR/CRP!</i></span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Hypercoagulable States / Thrombophilia</b> (young patients: APS, Sickle cell).</span></p><h3><b>3. Clinical Picture</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl dx\"><b>SUDDEN, PAINLESS, PROFOUND MONOCULAR VISION LOSS</b></mark> (often \"Counting Fingers\" or \"Light Perception\" over seconds!) + <b>Marked Positive RAPD (Marcus Gunn pupil)</b>!</li>\n<li class=\"l1\"><b>Pathognomonic Fundoscopy:</b> <b>Diffusely PALE, milky-white ischemic retina</b> with a stark <b>\"CHERRY-RED SPOT\" at the Macula/Fovea</b> (fovea is thin and supplied by intact underlying choroid!) + <b>\"Boxcarring\"</b> (segmented blood flow) in narrow arterioles!</li>\n</ul><h3><b>4. Emergency Action &amp; Workup</b></h3><ul>\n<li class=\"l1\"><b>Immediate Attempt to Dislodge Embolus (Within &lt; 4–6 Hours):</b> <b>Digital Ocular Massage</b> (firm pressure 10 sec, release 5 sec), <mark class=\"hl rx\"><b>IV Acetazolamide 500 mg</b></mark> (or Anterior Chamber Paracentesis) to abruptly drop IOP and improve perfusion pressure!</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>MANDATORY SYSTEMIC STROKE WORKUP:</b></mark> <mark class=\"hl mech\"><b>Check STAT ESR &amp; CRP</b></mark> (if &gt; 50 yrs -&gt; <mark class=\"hl lab\"><b>give IV Methylprednisolone immediately if GCA suspected</b></mark> to save the OTHER eye!), <mark class=\"hl mech\"><b>Brain MRI/DWI</b></mark> (high rate of concurrent silent cerebral strokes!), <b>Carotid Duplex/CTA</b>, <mark class=\"hl mech\"><b>ECG + Echocardiogram</b></mark> , Antiplatelets/Statin!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u310\">← Case 18</button><button class=\"nv\" data-u=\"u312\">Case 20 →</button></nav></article><article class=\"view unit\" id=\"u312\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 20</span><h1>Central Retinal Vein Occlusion (CRVO — &quot;BLOOD &amp; THUNDER&quot; FUNDUS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Central+Retinal+Vein+Occlusion+%28CRVO+%E2%80%94+%22BLOOD+%26+THUNDER%22+FUNDUS%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Etiology</b></h3><p>Thrombosis of the Central Retinal Vein at the lamina cribrosa, driven by <b>Hypertension, Diabetes Mellitus, Hyperlipidemia, Open-Angle Glaucoma</b>, and hypercoagulable states/hyperviscosity (Polycythemia, Multiple Myeloma, OCPs in young women).</p><h3><b>2. Clinical Picture &amp; Investigations</b></h3><ul>\n<li class=\"l1\"><mark class=\"hl dx\"><b>Sudden or subacute PAINLESS monocular vision loss</b></mark> (usually less catastrophic than CRAO, though severe in ischemic CRVO!).</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Pathognomonic Fundoscopy — \"BLOOD AND THUNDER\" APPEARANCE:</b></mark> Diffuse <mark class=\"hl lab\"><b>flame-shaped retinal hemorrhages across ALL 4 QUADRANTS</b></mark> , <b>dilated tortuous retinal veins</b>, <b>cotton-wool spots</b>, and <b>optic disc edema</b>!</li>\n<li class=\"l1\"><b>OCT Macula:</b> Assesses <b>Macular Edema</b> (#1 cause of vision loss in CRVO!).</li>\n</ul><h3><b>3. Complications &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Major Complication (~90–100 Days Post-CRVO — \"90-Day Glaucoma\"):</b> Retinal ischemia triggers <b>VEGF</b> (Vascular Endothelial Growth Factor) release -&gt; <b>Neovascularization of the Iris (Rubeosis Iridis)</b> -&gt; <b>Neovascular Glaucoma</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>Intravitreal Anti-VEGF Injections</b> (<b>Ranibizumab, Aflibercept, Bevacizumab</b>) for macular edema + <b>Panretinal Photocoagulation (PRP Laser)</b> if ischemic neovascularization develops + aggressive <mark class=\"hl mech\"><b>BP / Glucose / IOP control</b></mark> !</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u311\">← Case 19</button><button class=\"nv\" data-u=\"u313\">Case 21 →</button></nav></article><article class=\"view unit\" id=\"u313\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 21</span><h1>Retinal Detachment (RD) &amp; Posterior Vitreous Detachment (PVD)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Retinal+Detachment+%28RD%29+%26+Posterior+Vitreous+Detachment+%28PVD%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Etiology (Separated — 3 Types of RD)</b></h3><p>Separation of the <b>neurosensory retina</b> from the underlying <b>retinal pigment epithelium (RPE)</b>:</p>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Rhegmatogenous RD (#1 Overall!):</b> Caused by a <b>retinal tear/break</b> allowing liquefied vitreous fluid under the retina (<i>Risk factors:</i> <b>High Myopia</b>, <b>Prior Cataract Surgery</b>, <b>Eye Trauma</b>, Age-related <b>PVD</b>!).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Tractional RD:</b> Fibrovascular membranes pull retina off without a tear (<b>Proliferative Diabetic Retinopathy</b>, Sickle cell, ROP!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Exudative (Serous) RD:</b> Subretinal fluid accumulation without tear/traction (Choroidal tumor/melanoma, <b>VKH</b> [Vogt-Koyanagi-Harada], Severe HTN/Preeclampsia!).</span></p><h3><b>2. Clinical Picture (CRITICAL WARNING SIGNS — REFER SAME DAY!)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Sudden new shower of \"Floaters\"</b> (cobwebs/spots) + <b>Flashes of Light (Photopsia)</b> (vitreous tugging on retina — <b>PVD / Retinal Tear!</b>).</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\">Followed by a <mark class=\"hl dx\"><b>PAINLESS \"DARK CURTAIN OR VEIL\" descending/spreading across the visual field</b></mark> -&gt; <mark class=\"hl lab\"><b>Retinal Detachment!</b></mark></span></p>\n<ul>\n<li class=\"l1\"><b>Exam:</b> <b>Decreased Red Reflex</b>, billowing gray detached retinal folds on dilated fundoscopy, <b>RAPD</b> if extensive!</li>\n</ul><h3><b>3. Treatment</b></h3><ul>\n<li class=\"l1\"><b>PVD With Retinal Tear (No Detachment Yet):</b> <b>Immediate Laser Photocoagulation or Cryopexy</b> around tear (welds retina down — prevents detachment!).</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Rhegmatogenous Retinal Detachment:</b></mark> <b>Urgent Vitreoretinal Surgery</b> (<b>Pars Plana Vitrectomy [PPV]</b>, <b>Scleral Buckle</b>, or <b>Pneumatic Retinopexy</b> — <b>EMERGENT within 24 hrs if \"Macula-ON\"</b> to preserve central 20/20 vision!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u312\">← Case 20</button><button class=\"nv\" data-u=\"u314\">Case 22 →</button></nav></article><article class=\"view unit\" id=\"u314\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 22</span><h1>Diabetic Retinopathy (NPDR VS. PDR &amp; MACULAR EDEMA)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Diabetic+Retinopathy+%28NPDR+VS.+PDR+%26+MACULAR+EDEMA%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Pathophysiology</b></h3><p>Leading cause of <b>new blindness in working-age adults (20–74 years)</b>! Chronic hyperglycemia damages retinal capillary <b>pericytes</b>, causing microaneurysms, vascular leakage, capillary non-perfusion, and ischemia-driven <b>VEGF</b> release.</p><h3><b>2. Staging &amp; Classic Fundoscopy Findings</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>NPDR (Non-Proliferative Diabetic Retinopathy — Early/Moderate/Severe):</b></span></p>\n<ul>\n<li class=\"l2\"><b>Microaneurysms</b> (earliest sign — tiny red dots!), <b>Dot-and-blot hemorrhages</b>, <b>Hard Exudates</b> (yellow lipid deposits), <b>Cotton-Wool Spots</b> (nerve fiber layer infarcts), venous beading.</li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>PDR (Proliferative Diabetic Retinopathy — Vision-Threatening!):</b></span></p>\n<ul>\n<li class=\"l2\"><mark class=\"hl lab\"><b>HALLMARK = NEOVASCULARIZATION</b></mark> (<b>NVD</b> [on Optic Disc] or <b>NVE</b> [Elsewhere])! Fragile new vessels bleed easily causing <b>Sudden Painless Vitreous Hemorrhage</b> (sudden showers of floaters/cobwebs -&gt; sudden severe vision drop!) and <b>Tractional Retinal Detachment</b>!</li>\n</ul>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Diabetic Macular Edema (DME — #1 Cause of Decreased Central Visual Acuity in Diabetics!):</b> Retinal thickening/hard exudates at macula (occurs at <i>any</i> stage!).</span></p><h3><b>3. Screening &amp; Treatment</b></h3><ul>\n<li class=\"l1\"><b>Mandatory Dilated Fundoscopy Screening:</b> <mark class=\"hl lab\"><b>T1DM:</b></mark> 5 years after diagnosis, then annually | <mark class=\"hl lab\"><b>T2DM:</b></mark> <b>AT TIME OF DIAGNOSIS</b>, then annually! <i>(Pregnancy worsens DR -&gt; check every trimester!)</i></li>\n<li class=\"l1\"><b>Treatment:</b></li>\n<li class=\"l2\"><b>Cornerstone Prevention:</b> Tight glycemic (<mark class=\"hl mech\"><b> HbA1c &lt; 7%</b></mark> ) &amp; <b>BP control (&lt; 130/80)</b> + Fenofibrate/Statins.</li>\n<li class=\"l2\"><b>DME:</b> <b>Intravitreal Anti-VEGF Injections</b> (Aflibercept / Ranibizumab / Bevacizumab — First-Line!).</li>\n<li class=\"l2\"><b>PDR:</b> <b>Panretinal Photocoagulation (PRP Laser)</b> and/or <b>Intravitreal Anti-VEGF</b> (+/- <b>Vitrectomy</b> for non-clearing vitreous hemorrhage or tractional RD!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u313\">← Case 21</button><button class=\"nv\" data-u=\"u315\">Case 23 →</button></nav></article><article class=\"view unit\" id=\"u315\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 23</span><h1>Hypertensive Retinopathy</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Hypertensive+Retinopathy\">🔍 Search on Google</a></header><h4><b>Keith-Wagener-Barker Grading (Fundoscopic Window Into Systemic Vascular Damage!)</b></h4><ul>\n<li class=\"l1\"><b>Grade I:</b> Mild generalized <b>arteriolar narrowing</b> (\"silver/copper-wiring\").</li>\n<li class=\"l1\"><b>Grade II:</b> Focal arteriolar narrowing + <b>Arteriovenous (AV) Nicking</b> (thickened arteriole indents underlying vein!).</li>\n<li class=\"l1\"><b>Grade III:</b> Grade II <b>PLUS</b> <b>Flame-Shaped Hemorrhages</b>, <b>Cotton-Wool Spots</b>, and <b>Hard Exudates</b> (\"Macular Star\").</li>\n<li class=\"l1\"><mark class=\"hl lab\"><b>Grade IV (MALIGNANT HYPERTENSION — HYPERTENSIVE EMERGENCY!):</b></mark> Grade III <b>PLUS OPTIC DISC EDEMA (PAPILLEDEMA)</b>! -&gt; <b>Admit to ICU immediately</b> for controlled IV BP lowering!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u314\">← Case 22</button><button class=\"nv\" data-u=\"u316\">Case 24 →</button></nav></article><article class=\"view unit\" id=\"u316\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 24</span><h1>Age-Related Macular Degeneration (DRY VS. WET AMD)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Age-Related+Macular+Degeneration+%28DRY+VS.+WET+AMD%29\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Risk Factors</b></h3><p>Degenerative disease of the <b>macula</b> causing <b>progressive painless loss of CENTRAL vision</b> (difficulty reading, recognizing faces) while <b>peripheral vision remains intact</b>! <b>#1 Cause of Irreversible Legal Blindness in Elderly (&gt; 65 Years)!</b></p>\n<ul>\n<li class=\"l1\"><i>Strongest Modifiable Risk Factor:</i> <b>CIGARETTE SMOKING!</b> (+ Age, Family history, Fair skin, HTN).</li>\n</ul><h3><b>2. Crucial Comparison: Dry (Atrophic) vs. Wet (Neovascular/Exudative)</b></h3><table class=\"t \"><tr><td><p><b>Feature</b></p></td><td><p><b>Dry AMD (~85–90%)</b></p></td><td><p><b>Wet AMD (~10–15% — Causes ~90% of Severe Vision Loss!)</b></p></td></tr><tr><td><p><b>Pathology</b></p></td><td><p>Sub-RPE lipid deposits (<b>Drusen</b>) + Geographic atrophy</p></td><td><p><b>Choroidal Neovascularization (CNV)</b> leaking blood/fluid under macula!</p></td></tr><tr><td><p><b>Clinical Course</b></p></td><td><p><b>Slowly progressive</b> bilateral central blurring over years</p></td><td><p><b>RAPID, acute central vision loss</b> over days–weeks + <b>METAMORPHOPSIA (Straight lines appear WAVY/BENT on Amsler Grid!)</b></p></td></tr><tr><td><p><b>Fundoscopy &amp; OCT</b></p></td><td><p><b>Yellowish Drusen</b> in macula + RPE atrophy</p></td><td><p>Subretinal <b>hemorrhage, fluid, exudates</b>; confirm CNV with <b>OCT</b> / <b>Fluorescein Angiography</b></p></td></tr><tr><td><p><b>Treatment</b></p></td><td><p><b>Smoking cessation</b> + <b>AREDS2 Antioxidant/Zinc Vitamins</b> (slows progression in intermediate/advanced dry AMD — <i>avoid β-carotene in smokers -&gt; use Lutein/Zeaxanthin!</i>); Pegcetacoplan for geographic atrophy</p></td><td><p><b>URGENT Intravitreal Anti-VEGF Injections</b> (<b>Aflibercept, Ranibizumab, Faricimab, Bevacizumab</b>) — preserves &amp; often improves vision!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u315\">← Case 23</button><button class=\"nv\" data-u=\"u317\">Case 25 →</button></nav></article><article class=\"view unit\" id=\"u317\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 25</span><h1>Optic Neuritis vs. Ischemic Optic Neuropathy (AION)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Optic+Neuritis+vs.+Ischemic+Optic+Neuropathy+%28AION%29\">🔍 Search on Google</a></header><h4><b>High-Yield Differentiation of Acute Optic Neuropathy (Decreased Vision + Color Loss + RAPD!)</b></h4><table class=\"t \"><tr class=\"hd\"><th><p><b>Feature</b></p></th><th><p><b>Optic Neuritis</b></p></th><th><p><mark class=\"hl lab\"><b>Arteritic AION (AAION — GCA!)</b></mark></p></th><th><p><b>Non-Arteritic AION (NAION)</b></p></th></tr><tr><td><p><b>Classic Patient</b></p></td><td><p><b>Young Female (20–40 yrs)</b> — <mark class=\"hl lab\"><b>50% develop Multiple Sclerosis (MS)!</b></mark></p></td><td><p><b>Elderly (&gt; 50–70 yrs)</b> with <mark class=\"hl lab\"><b>Giant Cell Arteritis</b></mark> !</p></td><td><p><b>Middle-aged/Elderly (&gt; 50 yrs)</b> with <b>DM, HTN, \"Crowded\" small optic disc</b>, Nocturnal hypotension (<b>PDE-5 inhibitors/BP pills at night!</b>)</p></td></tr><tr><td><p><b>Pain &amp; Onset</b></p></td><td><p>Subacute (days) unilateral vision loss + <b>PAIN ON EYE MOVEMENT!</b></p></td><td><p><b>Sudden severe painless</b> monocular blindness <b>+ Headache, Jaw Claudication, Scalp Tenderness, Polymyalgia!</b></p></td><td><p><mark class=\"hl dx\"><b>Sudden PAINLESS</b></mark> monocular vision loss <b>upon waking in the morning!</b></p></td></tr><tr><td><p><b>Fundoscopy</b></p></td><td><p><b>Normal optic disc</b> in 2/3 (<b>\"Patient sees nothing &amp; doctor sees nothing\"</b> — Retrobulbar!) or mild disc swelling in 1/3</p></td><td><p><b>Chalky-white pale swollen optic disc</b></p></td><td><p><b>Hyperemic segmental optic disc swelling</b> + <b>Altitudinal visual field defect</b>!</p></td></tr><tr><td><p><mark class=\"hl mech\"><b>Labs / MRI &amp; Treatment</b></mark></p></td><td><p><mark class=\"hl mech\"><b>MRI Brain/Orbits with Gadolinium</b></mark> (check MS white matter plaques!) -&gt; <mark class=\"hl rx\"><b>High-Dose IV Methylprednisolone (1 g/day × 3–5 days) </b></mark>then oral taper! <i>(NEVER give low-dose oral Prednisone alone — increases recurrence!)</i></p></td><td><p><mark class=\"hl mech\"><b>STAT ESR &amp; CRP!</b></mark> <mark class=\"hl rx\"><b>IMMEDIATE IV Methylprednisolone 1 g/day × 3 days </b></mark>BEFORE Temporal Artery Biopsy to <b>save the fellow eye!</b></p></td><td><p>Check ESR/CRP to rule out GCA! No proven acute cure; control <mark class=\"hl lab\"><b>BP, DM, OSA</b></mark> , avoid nighttime BP dips!</p></td></tr></table><nav class=\"un\"><button class=\"nv\" data-u=\"u316\">← Case 24</button><button class=\"nv\" data-u=\"u318\">Case 26 →</button></nav></article><article class=\"view unit\" id=\"u318\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 26</span><h1>Papilledema vs. Pseudopapilledema</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Papilledema+vs.+Pseudopapilledema\">🔍 Search on Google</a></header><h3><b>1. Definition &amp; Clinical Picture</b></h3><ul>\n<li class=\"l1\"><b>Papilledema:</b> <b>BILATERAL optic disc swelling strictly secondary to Raised Intracranial Pressure (ICP)</b>!</li>\n<li class=\"l2\"><i>Classic Symptoms:</i> Headache (worse lying down/waking/coughing/Valsalva), nausea/projectile vomiting, <b>transient visual obscurations</b> (seconds-long blackouts on standing), <b>horizontal diplopia (CN VI false localizing sign)</b>.</li>\n<li class=\"l2\"><i>Early Vision:</i> <b>Visual acuity and pupillary reflexes are NORMAL initially</b> (unlike Optic Neuritis/AION where vision drops immediately — <i>if ICP stays high untreated -&gt; late optic atrophy &amp; blindness!</i>).</li>\n<li class=\"l2\"><i>Exam:</i> Blurred disc margins, hyperemia, <b>loss of spontaneous venous pulsations</b>, disc elevation, flame hemorrhages!</li>\n</ul><h3><b>2. Etiology of Papilledema (Separated)</b></h3><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>Intracranial Mass Lesion:</b> Brain tumor, Abscess, Subdural/Epidural/Intracerebral hematoma.</span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><mark class=\"hl mech\"><b>CSF Outflow / Venous Obstruction:</b></mark> Hydrocephalus, <b>Cerebral Venous Sinus Thrombosis</b>, Meningitis.</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><mark class=\"hl lab\"><b>Idiopathic Intracranial Hypertension (IIH / Pseudotumor Cerebri):</b></mark> Obese young female!</span></p><h3><b>3. Management &amp; Pseudopapilledema</b></h3><ul>\n<li class=\"l1\"><b>CRITICAL RULE:</b> <mark class=\"hl mech\"><b>Bilateral Papilledema = STAT Neuroimaging (MRI Brain + MRV, or CT Brain) BEFORE Lumbar Puncture!</b></mark> (Prevent fatal tonsillar herniation if a brain mass exists!).</li>\n<li class=\"l1\"><b>Pseudopapilledema:</b> Benign elevated disc mimicking papilledema without raised ICP (<b>Optic Disc Drusen</b> [autofluorescent calcified deposits on B-scan US/OCT!] or severe Hyperopia).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u317\">← Case 25</button><button class=\"nv\" data-u=\"u319\">Case 27 →</button></nav></article><article class=\"view unit\" id=\"u319\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 27</span><h1>Cranial Nerve Palsies (CN III, IV, VI) &amp; Hornerʼs Syndrome</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Cranial+Nerve+Palsies+%28CN+III%2C+IV%2C+VI%29+%26+Horner%CA%BCs+Syndrome\">🔍 Search on Google</a></header><h3><b>1. Cranial Nerve III (Oculomotor) Palsy — MEDICAL VS. SURGICAL (\"RULE OF THE PUPIL\"!)</b></h3><ul>\n<li class=\"l1\"><b>Exam:</b> Eye positioned <b>\"DOWN AND OUT\"</b> (unopposed Lateral Rectus [CN VI] &amp; Superior Oblique [CN IV]) + <b>Severe Ptosis</b>!</li>\n<li class=\"l1\"><b>THE GOLDEN EMERGENCY DISTINCTION:</b></li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>PUPIL-INVOLVING CN III PALSY (\"Surgical\" — Dilated, Fixed, Non-Reactive Pupil!):</b></mark> Parasympathetic fibers sit on the <i>superficial outer surface</i> of CN III -&gt; <b>COMPRESSED BY A POSTERIOR COMMUNICATING ARTERY (PCom) ANEURYSM!</b> -&gt; <b>STAT CTA / MRA Brain</b> (risk of fatal <mark class=\"hl lab\"><b>Subarachnoid Hemorrhage</b></mark> !).</li>\n<li class=\"l2\"><mark class=\"hl lab\"><b>PUPIL-SPARING CN III PALSY (\"Medical\" — Normal Reactive Pupil!):</b></mark> Microvascular ischemia of central core (<b>Diabetes Mellitus, Hypertension</b>) -&gt; resolves spontaneously in ~3 months! <i>(Still obtain MRI/MRA if atypical or non-resolving!)</i></li>\n</ul><h3><b>2. CN IV (Trochlear) &amp; CN VI (Abducens) Palsies</b></h3><ul>\n<li class=\"l1\"><b>CN IV (Superior Oblique):</b> <b>Vertical diplopia</b> worse when <b>looking DOWN &amp; IN (reading or walking down stairs!)</b> -&gt; patient <b>tilts head AWAY from affected side </b>(trauma = #1 cause!).</li>\n<li class=\"l1\"><b>CN VI (Lateral Rectus):</b> <b>Horizontal diplopia</b> (fails to abduct eye; <b>esotropia</b>) -&gt; causes: Microvascular DM/HTN, <b>Raised ICP</b> (false localizing sign!), Nasopharyngeal carcinoma, Trauma.</li>\n</ul><h3><b>3. Horner’s Syndrome (Sympathetic Chain Lesion)</b></h3><ul>\n<li class=\"l1\"><b>Classic Triad:</b> <b>(1) Mild Ptosis</b> (Müller’s muscle), <b>(2) Miosis</b> (constricted pupil — <b>anisocoria worse in the DARK!</b>), <b>(3) Anhidrosis</b> (loss of ipsilateral facial sweating).</li>\n<li class=\"l1\"><b>MUST RULE OUT:</b> <b>Pancoast (Apical Lung) Tumor</b>, <b>Carotid Artery Dissection</b> (painful Horner’s + neck pain/stroke!), Cavernous sinus lesion, Neuroblastoma (if congenital/infant!).</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u318\">← Case 26</button><button class=\"nv\" data-u=\"u320\">Case 28 →</button></nav></article><article class=\"view unit\" id=\"u320\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 28</span><h1>Pupillary Abnormalities (ESSENTIAL BEDSIDE SIGNS)</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pupillary+Abnormalities+%28ESSENTIAL+BEDSIDE+SIGNS%29\">🔍 Search on Google</a></header><p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><b>RAPD (Relative Afferent Pupillary Defect / Marcus Gunn Pupil):</b></span></p>\n<ul>\n<li class=\"l2\"><i>Swinging Flashlight Test:</i> Shining light in <b>affected eye</b> causes <mark class=\"hl lab\"><b>BOTH pupils to PARADOXICALLY DILATE</b></mark> (because the eye detects less light than the healthy eye just tested!).</li>\n<li class=\"l2\"><i>Indicates:</i> <b>Unilateral Optic Nerve Disease</b> (Optic Neuritis, AION, Advanced Glaucoma) OR <b>Massive Retinal Pathology</b> (CRAO, Total Retinal Detachment) — <i>NEVER caused by Cataract or Refractive error!</i></li>\n</ul>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Adie’s Tonic Pupil:</b> Benign post-ganglionic ciliary ganglion denervation (young females); <b>unilateral dilated pupil</b> reacting poorly to light, <b>slowly constricting to near </b>(\"light-near dissociation\") + <b>absent knee/ankle jerks</b> (Holmes-Adie syndrome).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Argyll Robertson Pupil (\"Prostitute’s Pupil\"):</b> Bilateral small irregular pupils that <b>\"accommodate but do NOT react to light\"</b> -&gt; Classic for <b>Neurosyphilis</b> (or severe DM autonomic neuropathy!).</span></p><nav class=\"un\"><button class=\"nv\" data-u=\"u319\">← Case 27</button><button class=\"nv\" data-u=\"u321\">Case 29 →</button></nav></article><article class=\"view unit\" id=\"u321\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 29</span><h1>Pediatric Ophthalmology — Leukocoria (RETINOBLASTOMA!), Strabismus &amp; Amblyopia</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Pediatric+Ophthalmology+%E2%80%94+Leukocoria+%28RETINOBLASTOMA%21%29%2C+Strabismus+%26+Amblyopia\">🔍 Search on Google</a></header><h3><b>1. Leukocoria (\"White Pupillary Reflex\" — ALWAYS AN URGENT EMERGENCY!)</b></h3><ul>\n<li class=\"l1\"><b>Definition:</b> Absent red reflex (seen on newborn screening or flash photographs!) replaced by a white glow.</li>\n<li class=\"l1\"><mark class=\"hl mech\"><b>Etiology (Separated — RULE OUT CANCER FIRST!):</b></mark></li>\n</ul>\n<p class=\"num\"><span class=\"n\">1.</span><span class=\"nt\"><mark class=\"hl mech\"><b>RETINOBLASTOMA (#1 Most Lethal Cause — </b></mark><i><b>RB1</b></i><mark class=\"hl mech\"><b> Tumor Suppressor Mutation!):</b></mark> Presents &lt; 2–3 yrs with <b>Leukocoria (#1 sign!)</b> and/or <b>Strabismus (#2 sign!)</b>. <i>Confirm with </i><mark class=\"hl mech\"><i><b>Ophthalmic Exam + Ultrasound / MRI Orbits</b></i></mark><i> (shows intraocular calcifications; </i><i><b>NEVER biopsy</b></i><i> due to tumor seeding! </i><i><b>Avoid CT radiation</b></i><i> if germline RB1 -&gt; osteosarcoma risk!).</i></span></p>\n<p class=\"num\"><span class=\"n\">2.</span><span class=\"nt\"><b>Congenital Cataract</b> (#1 overall benign/treatable cause -&gt; <b>operate urgently within first 6–8 weeks of life</b> to prevent permanent blindness!).</span></p>\n<p class=\"num\"><span class=\"n\">3.</span><span class=\"nt\"><b>Persistent Fetal Vasculature</b>, <b>Retinopathy of Prematurity (ROP)</b>, <b>Toxocariasis</b>, <b>Coats’ Disease</b>.</span></p><h3><b>2. Strabismus (Ocular Misalignment) &amp; Amblyopia (\"Lazy Eye\")</b></h3><ul>\n<li class=\"l1\"><b>Diagnosis:</b> <b>Hirschberg Corneal Light Reflex Test</b> (asymmetric reflection) + <b>Cover-Uncover Test</b>! <i>(Exclude </i><i><b>Pseudostrabismus</b></i><i> from wide flat nasal bridge in infants: symmetric corneal light reflex!).</i></li>\n<li class=\"l1\"><b>Why Urgent in Kids &lt; 7–8 Years?</b> Brain suppresses the deviated/blurry eye -&gt; irreversible cortical visual loss (<b>Amblyopia</b>)!</li>\n<li class=\"l1\"><b>Treatment:</b> Correct refractive error (glasses — accommodative esotropia resolves with hyperopic glasses!) + <mark class=\"hl rx\"><b>Patching (or Atropine drops) of the GOOD/DOMINANT eye</b></mark> (forces brain to use amblyopic eye!) +/- Strabismus muscle surgery!</li>\n</ul><nav class=\"un\"><button class=\"nv\" data-u=\"u320\">← Case 28</button><button class=\"nv\" data-u=\"u322\">Case 30 →</button></nav></article><article class=\"view unit\" id=\"u322\" hidden style=\"--c:#c2185b\"><button class=\"back\" data-p=\"12\">← Ophthalmology</button><header class=\"uh\"><span class=\"ul\">Case 30</span><h1>Retinopathy of Prematurity (ROP), Congenital Glaucoma &amp; Cnldo</h1><a class=\"gb\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?q=Retinopathy+of+Prematurity+%28ROP%29%2C+Congenital+Glaucoma+%26+Cnldo\">🔍 Search on Google</a></header><h3><b>1. Retinopathy of Prematurity (ROP)</b></h3><ul>\n<li class=\"l1\"><b>At-Risk Infants:</b> Premature infants (<b>&lt; 30–32 weeks gestation</b> or birth weight <b>&lt; 1,500 g</b>) exposed to high supplemental <b>Oxygen</b> in <b>NICU</b>!</li>\n<li class=\"l1\"><b>Pathophysiology:</b> Hyperoxia suppresses <b>VEGF</b> -&gt; halts normal retinal vessel growth -&gt; later hypoxia causes massive rebound <b>VEGF surge</b> -&gt; abnormal retinal neovascularization -&gt; <b>Tractional Retinal Detachment &amp; Leukocoria</b>!</li>\n<li class=\"l1\"><b>Prevention &amp; Treatment:</b> Target <mark class=\"hl mech\"><b>SpO2 90–95%</b></mark> in NICU; mandatory dilated <b>ROP screening</b> at 4–6 wks of life -&gt; <b>Laser Photocoagulation</b> or <b>Intravitreal Anti-VEGF </b>if threshold disease!</li>\n</ul><h3><b>2. Primary Congenital Glaucoma (\"Buphthalmos\")</b></h3><ul>\n<li class=\"l1\"><b>Classic Triad in Infant (&lt; 1 Year):</b> <b>(1) Epiphora (excess tearing)</b> + <b>(2) Photophobia</b> + <b>(3) Blepharospasm</b> -&gt; accompanied by <b>Cloudy Edematous Enlarged Cornea (&gt; 12 mm, \"Ox-Eye / Buphthalmos\")</b> and <b>Haab’s Striae</b>!</li>\n<li class=\"l1\"><b>Treatment:</b> <b>URGENT Surgery (Goniotomy or Trabeculotomy)</b>!</li>\n</ul><h3><b>3. Congenital Nasolacrimal Duct Obstruction (CNLDO — Most Common Cause of Tearing in Newborns!)</b></h3><ul>\n<li class=\"l1\"><b>Pathology:</b> Persistent membrane at <b>Valve of Hasner</b> (distal nasolacrimal duct).</li>\n<li class=\"l1\"><b>Clinical Picture:</b> Persistent <b>unilateral/bilateral tearing (epiphora)</b> &amp; mucoid crusting since birth, <b>WHITE quiet conjunctiva</b> (no redness/photophobia, normal cornea — distinguishes from Congenital Glaucoma!).</li>\n<li class=\"l1\"><b>Treatment:</b> <b>~90% Resolve Spontaneously by 9–12 Months!</b> Teach parents <b>Crigler Lacrimal Sac Massage</b> (press downward over lacrimal sac 2–3×/day) + warm cleaning; if persistent <b>&gt; 12 months</b> -&gt; <b>Nasolacrimal Duct Probing</b>!</li>\n</ul>\n<p class=\"muted\"><i>End of Part 12B — Ophthalmology (30 Cases Complete!)</i></p><nav class=\"un\"><button class=\"nv\" data-u=\"u321\">← Case 29</button></nav></article>"});
